#include <stdio.h>
      #include <string.h>

      char *my_strcat(char *dest, const char *src) {
          char *p = dest;
          while (*p != '\0') p++;
          while (*src != '\0') { *p = *src; p++; src++; }
          *p = '\0';
          return dest;
      }

      int main(void) {
          char a[256], b[256];
          fgets(a, sizeof(a), stdin);
          a[strcspn(a, "\n")] = 0;
          fgets(b, sizeof(b), stdin);
          b[strcspn(b, "\n")] = 0;
